`timescale 1ns/1ps
`include "build/mono_recognition_20261028/fixtures/android_upload_meta.vh"
// Bytes below are generated by the Android recognition/ScoreTransfer test,
// rather than a second reimplementation of the upload protocol in this TB.
module tb_melody_upload_endpoint;
 reg clk=0;always #5 clk=~clk;
 reg rst_n=0,rx_valid=0,tx_ready=0;reg[7:0]rx_byte=0;
 wire tx_valid,remote_valid,link_activity;wire[7:0]tx_byte;
 wire score_request_valid,score_response_valid;wire[7:0]score_request_type,score_request_seq,score_request_length;
 wire[111:0]score_request_payload,score_response_payload;
 wire playing,paused,guiding,finished,timbre,start_pulse,ready,gate;
 wire[9:0]step;wire[2:0]bank,pad;wire[5:0]note;wire[6:0]guide_led;
 reg[7:0]bytes[0:`FIXTURE_BYTES-1];integer index,len,k,t,acks=0,notes=0,clocks=0;
 reg gate_last=0;reg[7:0]response[0:19];reg[7:0]crc;
 ble_control_endpoint #(.EXTENDED_STATE(1),.SONG_EXTENSIONS(1),.REALTIME_NOTES(1),.SCORE_UPLOAD(1)) ep(
  .clk(clk),.rst_n(rst_n),.rx_valid(rx_valid),.rx_byte(rx_byte),.write_enable(1'b1),
  .bank(3'd0),.timbre(1'b1),.volume(5'd16),.vibrato(1'b0),.ui_state(2'd0),.song_index(8'd0),
  .guide_step(11'd0),.guide_target(3'd0),.guide_target_bank(3'd0),.playback_state(2'd0),
  .vibrato_depth(4'd0),.bend(8'd128),.led_mode(2'd0),.effect_mask(3'd0),.oled_contrast(8'h7f),
  .pad_mask(7'd0),.telemetry(72'd0),.remote_valid(remote_valid),.link_activity(link_activity),
  .tx_valid(tx_valid),.tx_byte(tx_byte),.tx_ready(tx_ready),
  .score_request_valid(score_request_valid),.score_request_type(score_request_type),.score_request_seq(score_request_seq),
  .score_request_length(score_request_length),.score_request_payload(score_request_payload),
  .score_response_valid(score_response_valid),.score_response_payload(score_response_payload));
 uploaded_song_engine #(.CYCLES_PER_MS(10),.UPLOAD_TIMEOUT_MS(5000)) engine(
  .clk(clk),.rst_n(rst_n),.link_active(1'b1),.request_valid(score_request_valid),.request_type(score_request_type),
  .request_seq(score_request_seq),.request_length(score_request_length),.request_payload(score_request_payload),
  .response_valid(score_response_valid),.response_payload(score_response_payload),.stop_external(1'b0),
  .strike_valid(1'b0),.strike_pad(3'd0),.playing(playing),.paused(paused),.guiding(guiding),.finished(finished),
  .timbre(timbre),.start_pulse(start_pulse),.ready(ready),.gate(gate),.step(step),.bank(bank),.pad(pad),.note(note),.guide_led(guide_led));
 function[7:0]cb;input[7:0]a,b;reg[7:0]c;integer j;
 begin c=a^b;for(j=0;j<8;j=j+1)c=c[7]?(c<<1)^8'h07:c<<1;cb=c;end endfunction
 task send;input[7:0]b;begin @(negedge clk);rx_valid=1;rx_byte=b;@(negedge clk);rx_valid=0;end endtask
 always @(negedge clk)begin
  if(gate && !gate_last)notes=notes+1;
  gate_last=gate;
  if(playing && !finished)clocks=clocks+1;
 end
 initial begin
  $readmemh("D:/FPGA/Projects/soundcore_2026/build/mono_recognition_20261028/fixtures/android_upload.hex",bytes);
  repeat(4)@(negedge clk);rst_n=1;index=0;
  while(index<`FIXTURE_BYTES)begin
   len=6+bytes[index+4];
   for(k=0;k<len;k=k+1)send(bytes[index+k]);
   t=0;while(!tx_valid && t<100)begin @(negedge clk);t=t+1;end
   if(!tx_valid)$fatal(1,"endpoint timeout");
   // Backpressure must hold the response byte stable.
   repeat(4)@(negedge clk);
   if(tx_byte!=8'ha5)$fatal(1,"response lost to backpressure");
   tx_ready=1;k=0;
   while(tx_valid)begin response[k]=tx_byte;k=k+1;@(negedge clk);end
   tx_ready=0;acks=acks+1;
   if(k!=20 || response[2]!=8'h82 || response[3]!=bytes[index+3] || response[4]!=14 || response[7]!=0)
    $fatal(1,"invalid score ACK len=%0d type=%h error=%h",k,response[2],response[7]);
   crc=0;for(k=1;k<19;k=k+1)crc=cb(crc,response[k]);
   if(crc!=response[19])$fatal(1,"ACK frame CRC8 mismatch");
   index=index+len;
  end
  if(!ready || !playing || engine.active_count!=`FIXTURE_EVENTS || engine.active_crc!=`FIXTURE_CRC)
   $fatal(1,"Android score did not commit and start");
  t=0;while(!finished && t<500000)begin @(negedge clk);t=t+1;end
  if(!finished || step!=`FIXTURE_EVENTS || notes!=12)$fatal(1,"full score events/attacks %0d %0d",step,notes);
  if(clocks<`FIXTURE_MS*10-20 || clocks>`FIXTURE_MS*10+60)$fatal(1,"timing drift clocks=%0d",clocks);
  $display("PASS: Android recognized score bytes -> endpoint ACK/CRC -> atomic RAM -> %0d autonomous note attacks, %0d ACKs, %0d clocks",notes,acks,clocks);$finish;
 end
 initial begin #6000000;$fatal(1,"global timeout");end
endmodule
